{"path":"index.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>{{BUSINESS_NAME}} — A local pause in sound</title>
  <meta name='description' content='Slow down with curated sound and gentle guidance — gatherings, private sessions, and short-series support for clarity.'>
  <link rel='stylesheet' href='assets/css/styles.css'>
</head>
<body class='page-asym'>
  <header class='site-header'>
    <div class='wrap'>
      <a class='brand' href='index.html' aria-label='home'>
        <svg width='40' height='40' viewBox='0 0 100 100' aria-hidden='true'>
          <rect x='0' y='0' width='100' height='100' fill='url("assets/img/pattern.svg#pattern")'></rect>
        </svg>
        <strong class='brand-name'>{{BUSINESS_NAME}}</strong>
      </a>
      <nav class='main-nav' aria-label='Site'>
        <ul>
          <li><a href='events.html'>Gatherings</a></li>
          <li><a href='private-sessions.html'>Privates</a></li>
          <li><a href='pricing.html'>Investments</a></li>
          <li><a href='about.html'>Stories</a></li>
          <li><a href='faq.html'>FAQ</a></li>
          <li><a class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a></li>
        </ul>
      </nav>
      <button id='tryBtn' class='try-btn'>Try it now</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class='hero section' data-reveal>
      <div class='wrap hero-grid'>
        <div class='hero-copy'>
          <h1>Quiet made intentional</h1>
          <p class='lead'>Guided gatherings and private sessions that give space to rest, notice, and a gentle re-set. Simple frameworks, practical takeaways.</p>
          <p class='muted'>Next gathering: <a href='events.html#next-event' id='next-event-link'>See details</a></p>
          <div class='hero-actions'>
            <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>Reserve a Pause</a>
            <button id='tryNow' class='btn ghost'>Begin a Short Exercise</button>
          </div>
        </div>
        <div class='hero-visual' aria-hidden='true'>
          <div class='masonry' aria-hidden='true'>
            <div class='tile tall'>
              <svg viewBox='0 0 100 100' class='tile-pattern'><defs><linearGradient id='g1' x1='0' x2='1'><stop offset='0' stop-color='#6B6' /><stop offset='1' stop-color='#499' /></linearGradient></defs><rect width='100' height='100' fill='url(#g1)' /></svg>
            </div>
            <div class='tile'>
              <div class='card small'>Evening circle — sound + space</div>
            </div>
            <div class='tile wide'>
              <div class='card small'>Private Harbor sessions</div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- STORY (why this approach) -->
    <section class='story section' data-reveal>
      <div class='wrap'>
        <h2>How we shape a moment</h2>
        <p>We blend steady instruments, clear spoken guidance, and short practical practices so you leave with a small set of tools. Sessions are intentionally concise or gently expansive depending on the offering.</p>
        <ul>
          <li>Short structure so you can use what you learned right away</li>
          <li>Clear prompts for reflection and intention-setting</li>
          <li>Accessible for first timers & regulars alike</li>
        </ul>
      </div>
    </section>

    <!-- FRAMEWORK: asym_masonry showcase -->
    <section class='framework section' data-reveal>
      <div class='wrap'>
        <h2>Our session shapes</h2>
        <div class='asym-grid'>
          <article class='card reveal-item'>
            <h3>Single Drift</h3>
            <p class='price'>$28 — Drop-in</p>
            <p>45 minutes: a compact, seated session for re-centring during a busy week.</p>
          </article>
          <article class='card reveal-item'>
            <h3>Resonance Series</h3>
            <p class='price'>$160 — 6 sessions</p>
            <p>A short-series for steady practice and gentle momentum toward clarity.</p>
          </article>
          <article class='card reveal-item'>
            <h3>Private Harbor</h3>
            <p class='price'>$120 — 60 min</p>
            <p>One-to-one sessions designed for a quieter, tailored exploration.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- OFFERS: retail_addon -->
    <section class='offers section' data-reveal>
      <div class='wrap'>
        <h2>Retail + add-ons</h2>
        <p>Small, tactile supports to carry the session beyond the room.</p>
        <div class='products'>
          <div class='product'>
            <strong>Handstone</strong>
            <span class='p-price'>$18</span>
            <p>a smooth palm-stone for grounding practices</p>
          </div>
          <div class='product'>
            <strong>Series Pass</strong>
            <span class='p-price'>$140</span>
            <p>Save by buying the full 6-session resonance series at once</p>
          </div>
          <div class='product'>
            <strong>Journal Add-on</strong>
            <span class='p-price'>$12</span>
            <p>Minimal guided pages for reflection between sessions</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PRICING summary -->
    <section class='pricing section' data-reveal>
      <div class='wrap'>
        <h2>Investment</h2>
        <p>Clear, tiered options — pick the rhythm that fits your life.</p>
        <div class='pricing-grid'>
          <div class='plan'>
            <h3>Drop-in</h3>
            <p class='price'>$28</p>
            <p>One session at a time</p>
          </div>
          <div class='plan featured'>
            <h3>Series</h3>
            <p class='price'>$160</p>
            <p>Six-session track for steady practice</p>
          </div>
          <div class='plan'>
            <h3>Private</h3>
            <p class='price'>$120</p>
            <p>One-to-one guidance and space</p>
          </div>
        </div>
        <p class='small muted'>Contraindications: Sound baths and guided breathwork may not be appropriate for people with severe hearing impairment, recent surgery, pregnancy without clearance from a care provider, epilepsy, or uncontrolled psychiatric conditions. If in doubt, consult your clinician before booking. If you need accommodations, reach out at {{EMAIL}}.</p>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section class='testimonials section' data-reveal>
      <div class='wrap'>
        <h2>Words from people who come back</h2>
        <blockquote>
          "A gentle reset I can actually practice during the week. I leave clearer and calmer."
          <cite>— A regular participant</cite>
        </blockquote>
      </div>
    </section>

    <!-- CTA -->
    <section class='cta section' data-reveal>
      <div class='wrap cta-panel'>
        <h2>Ready for a short pause?</h2>
        <p>Reserve a moment that meets your schedule — gatherings and privates available.</p>
        <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>Book your place</a>
      </div>
    </section>

  </main>

  <footer class='site-footer'>
    <div class='wrap'>
      <div class='footer-col'>
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}} — <a href='tel:{{PHONE}}'>{{PHONE}}</a>
      </div>
      <div class='footer-col'>
        <nav>
          <a href='events.html'>Gatherings</a>
          <a href='about.html'>About</a>
          <a href='contact.html'>Contact</a>
        </nav>
      </div>
      <div class='footer-col'>
        <a class='small' href='privacy.html'>Privacy</a>
        <a class='small' href='terms.html'>Terms</a>
      </div>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div id='exerciseModal' class='modal' aria-hidden='true'>
    <div class='modal-panel' role='dialog' aria-modal='true' aria-labelledby='exerciseTitle'>
      <button class='modal-close' id='closeModal' aria-label='Close'>×</button>
      <h3 id='exerciseTitle'>Short Exercise</h3>
      <div id='exerciseRoot'>
        <div class='exercise-choices'>
          <button class='ex-choice' data-mode='breath'>Breathing</button>
          <button class='ex-choice' data-mode='journal'>Journaling</button>
          <button class='ex-choice' data-mode='intention'>Set an Intention</button>
        </div>
        <div id='exerciseArea' class='exercise-area' hidden></div>
      </div>
    </div>
  </div>

  <script src='assets/js/main.js' defer></script>
</body>
</html>"} 
